/* 发布指挥台 · 内联数据：orders-api v2.4.0 生产发布运行手册
 * 全部数据随首屏内联，无任何网络请求。 */
window.FLOW = {
  meta: {
    product: "orders-api",
    version: "v2.4.0",
    runbook: "RLB-2.4",
    change: "CHG-20260919-042",
