    if (e.key === "Escape" && modalStepId) closeModal();
  });

  // ── 计时器 ─────────────────────────────────────────────────
  setInterval(function () {
    if (!S.finished) $("timer").textContent = fmtElapsed(Date.now() - S.startedAt);
  }, 1000);

  // ── 启动：数据内联，首屏即用 ───────────────────────────────
  initState();
  logEvent("发布演练开始：" + FLOW.meta.product + " " + FLOW.meta.version, "");
  render();
})();

